import ast,json,hashlib
from pathlib import Path
root=Path('/workspace');runtime=json.loads((root/'runtime_resolved.json').read_text());p=json.loads((root/'proposal.json').read_text())
def check(value,schema,path):
 typ=schema.get('type')
 if typ:
  assert {'object':isinstance(value,dict),'array':isinstance(value,list),'string':isinstance(value,str),'boolean':isinstance(value,bool)}[typ],(path,typ)
 if 'enum' in schema: assert value in schema['enum'],path
 if 'const' in schema: assert value==schema['const'],path
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  for i,v in enumerate(value): check(v,schema.get('items',{}),f'{path}[{i}]')
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=value.keys(),path
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert set(value)<=props.keys(),(path,set(value)-props.keys())
  for k,v in value.items():
   if k in props: check(v,props[k],path+'.'+k)
check(p['study'],runtime['study_schema'],'study')
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert len(p['variants'])==4 and len({v['name'] for v in p['variants']})==4
assert any(v['role']=='candidate' for v in p['variants'])
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 f=root/v['file'];tree=ast.parse(f.read_text());compile(tree,str(f),'exec')
 cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert cfg==v['config'];assert hashlib.sha256(f.read_bytes()).hexdigest() in v['note']
 assert v['role'] in ['candidate','control']
for a in p['knowledge_assessments']:
 assert set(a)=={'knowledge_id','decision','rationale','transformed_mechanism','variant_names','nearest_work_difference','falsifier'}
 assert a['decision'] in ['used','considered','rejected','unresolved']
 assert set(a['variant_names'])<={v['name'] for v in p['variants']}
assert (root/'candidate.py').read_bytes()==(root/'recent_separate.py').read_bytes()
# Source differences are confined to literal config/defaults; executable bodies match.
def normalized(name):
 t=ast.parse((root/name).read_text())
 for n in t.body:
  if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets):
   n.value=ast.Constant(None)
  if isinstance(n,ast.ClassDef) and n.name=='Model':
   init=next(x for x in n.body if isinstance(x,ast.FunctionDef) and x.name=='__init__')
   init.args.defaults=[ast.Constant(None) for _ in init.args.defaults]
 return ast.dump(t,include_attributes=False)
assert len({normalized(v['file']) for v in p['variants']})==1
print('PASS: full study schema, protocol, all evidence IDs, four unique standalone variants, roles, literal configs, source hashes, knowledge-assessment records and equal executable bodies.')
print('PASS: candidate.py equals recent_separate.py.')
print('Proposal bytes:',(root/'proposal.json').stat().st_size)
PY"

